// procura clientes pelo NIF; devolve uma lista vazia quando não há resultados
export async function porNif(nif: string): Promise<Cliente[]> {
  const res = await fetch(`/api/clientes?nif=${nif}`)
  return res.ok ? res.json() : []
}

