// sincroniza o stock com o ERP e ignora os artigos descontinuados
export async function sincronizar(erp: Erp) {
  for (const artigo of await erp.artigos())
    if (!artigo.descontinuado) await db.stock.upsert(artigo.sku, artigo.quantidade)
}
